# PRODUCTION START (API) — Riyadh Trust Bank (v0.8)
#
# Starts the production API on :8000 with production env loaded from
# .env.production (generated by scripts\production_setup.ps1).
# Foreground — Ctrl+C stops it. Single worker, no --reload, no Server
# header (uvicorn --no-server-header). Dev (:8000) and production
# (:8000) share the port on purpose — production IS the live instance
# on this machine; stop dev/staging before starting production, or
# the bind will fail (see docs\PRODUCTION.md § Runbook).
#
# Usage:  .\scripts\production_start.ps1
$ErrorActionPreference = "Stop"
$ROOT = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
$VENV = if ($env:RTB_PROD_VENV) { $env:RTB_PROD_VENV } else { Join-Path $env:USERPROFILE "rtb-prod-venv" }

$envFile = Join-Path $ROOT ".env.production"
if (-not (Test-Path $envFile)) {
    Write-Host "ERROR: $envFile not found — run .\scripts\production_setup.ps1 first."
    exit 1
}
if ((Get-Content $envFile -Raw) -match "REPLACE-ME-WITH-A-LONG-RANDOM-SECRET") {
    Write-Host "ERROR: .env.production still has the placeholder SECRET_KEY."
    Write-Host "Run .\scripts\production_setup.ps1 to generate a real one, or set it by hand:"
    Write-Host '  python -c "import secrets; print(secrets.token_urlsafe(64))"'
    exit 1
}
if (-not (Test-Path (Join-Path $VENV "Scripts\python.exe"))) {
    Write-Host "ERROR: production venv not found at $VENV — run .\scripts\production_setup.ps1 first."
    exit 1
}

# Load production env (SECRET_KEY, DATABASE_URL, CORS_ORIGINS, ...).
foreach ($line in (Get-Content $envFile)) {
    if ($line -match "^\s*#" -or $line -notmatch "=") { continue }
    $k, $v = $line.Split("=", 2)
    # Strip surrounding double quotes (e.g. DATABASE_URL="sqlite:///...").
    [Environment]::SetEnvironmentVariable($k.Trim(), $v.Trim().Trim('"'), "Process")
}
# Always force the production data dir to the absolute path.
$env:RTB_DATA_DIR = Join-Path $ROOT "data-prod"
$env:ENVIRONMENT = "production"

Write-Host "Production API starting on http://127.0.0.1:8000"
Write-Host "  ENVIRONMENT=$env:ENVIRONMENT  RTB_DATA_DIR=$env:RTB_DATA_DIR"
Write-Host "  DATABASE_URL=<redacted>"
Write-Host "  Demo accounts: OFF (RTB_DEMO_ACCOUNTS=$env:RTB_DEMO_ACCOUNTS)"
Write-Host "  Health: python scripts\healthcheck.py"
Set-Location (Join-Path $ROOT "backend")
& (Join-Path $VENV "Scripts\Activate.ps1")
& (Join-Path $VENV "Scripts\python.exe") -m uvicorn app.main:app --port 8000 --no-server-header
